local script=debug.getinfo(1,'S').source:sub(2);local dir=script:match('^(.*)[/\\]');package.path=dir..'/?.lua;'..package.path;local b=require('_bootstrap');local a=b.lib('args');local o=a.parse(arg);local path=b.lib('path');local time=b.lib('time');local host=b.lib('host');local root=path.absolute(a.required(o,'evidence-dir'));local markers={path.join(root,'team-1-runtime','screenshot.tick'),path.join(root,'team-2-runtime','screenshot.tick')};assert(time.poll(30000,100,function()return path.is_file(markers[1])and path.is_file(markers[2])end),'authoritative screenshot trigger timeout');time.sleep_ms(5000);for team=1,2 do local pid=a.integer(a.required(o,'team'..team..'-renderer-pid'),'renderer PID',1);host.call('screenshot',{pid=pid,output=path.join(root,'team-'..team..'-screenshot.png')})end
